logo":"https://commons.wikimedia.org/wiki/Special:FilePath/ZDFinfo_Logo.svg"},{"name":"phoenix","url":"https://zdf-hls-19.akamaized.net/hls/live/2016502/de/high/master.m3u8","available":true,"quality":"720p","logo":"https://commons.wikimedia.org/wiki/Special:FilePath/Phoenix_Logo.svg"},{"name":"KiKA","url":"https://kikageohls.akamaized.net/hls/live/2022693/livetvkika_de/master.m3u8","available":true,"quality":"1080p","logo":"https://commons.wikimedia.org/wiki/Special:FilePath/KiKA_Logo.svg"},{"name":"SWR Rheinland-Pfalz","url":"https://swrrpd-hls.akamaized.net/hls/live/2018676/swrrpd/master.m3u8","available":true,"quality":"720p","logo":""},{"name":"WDR","url":"https://wdr-live.ard-mcdn.de/wdr/live/hls/de/master.m3u8","available":true,"quality":"720p","logo":"https://commons.wikimedia.org/wiki/Special:FilePath/WDR_Logo.svg"},{"name":"NDR","url":"https://mcdn.ndr.de/ndr/hls/ndr_fs/ndr_hh/master.m3u8","available":true,"quality":"720p","logo":"https://commons.wikimedia.org/wiki/Special:FilePath/NDR_Logo.svg"},{"name":"MDR","url":"https://mdrtvsnhls.akamaized.net/hls/live/2016928/mdrtvsn/index.m3u8","available":true,"quality":"1080p","logo":"https://commons.wikimedia.org/wiki/Special:FilePath/MDR_Logo.svg"},{"name":"BR","url":"https://mcdn.br.de/br/fs/bfs_sued/hls/de/master.m3u8","available":true,"quality":"1080p","logo":"https://commons.wikimedia.org/wiki/Special:FilePath/BR_Fernsehen_Logo.svg"}]';
 $html='<section id="odpc-tv" data-channels="'.esc_attr($channels).'"><div class="odpc-tv-screen"><video id="odpc-tv-video" controls playsinline preload="none"></video><div id="odpc-tv-status" role="status">Sender auswählen</div></div><div class="odpc-tv-top"><h2>Sender</h2><input id="odpc-tv-search" type="search" aria-label="Sender suchen" placeholder="Suchen …"></div><div id="odpc-tv-grid"></div></section>';
 $html.='<style>#odpc-tv{max-width:1040px;margin:0 auto;color:#f5f8ff;font-family:inherit}#odpc-tv .odpc-tv-screen{background:#101827;border-radius:14px;overflow:hidden}#odpc-tv video{display:block;width:100%;aspect-ratio:16/9;background:#000}#odpc-tv-status{padding:8px 14px;font-size:13px;color:#c9d4e4}#odpc-tv .odpc-tv-top{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:18px 0 12px}#odpc-tv h2{margin:0;color:inherit;font-size:22px}#odpc-tv input{min-width:0;max-width:220px;width:48%;padding:10px 12px;border:1px solid #c7d0dc;border-radius:9px;background:#fff;color:#1c2738}#odpc-tv-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:9px}#odpc-tv-grid button{display:flex;align-items:center;justify-content:center;gap:8px;flex-direction:column;min-height:88px;padding:10px 6px;border:1px solid #dae1ea;border-radius:12px;background:#fff;color:#14253b;cursor:pointer;font:inherit;font-size:13px;line-height:1.25}#odpc-tv-grid button:hover:not(:disabled),#odpc-tv-grid button:focus-visible{border-color:#2679bd;background:#eef7ff}#odpc-tv-grid button.active{outline:2px solid #2679bd}#odpc-tv-grid button:disabled{opacity:.42;cursor:not-allowed}#odpc-tv-grid img{display:block;max-width:88px;width:auto;height:34px;object-fit:contain}#odpc-tv-grid .odpc-tv-fallback{display:flex;align-items:center;justify-content:center;font-weight:800;font-size:18px;height:34px}#odpc-tv-grid .odpc-tv-name{text-align:center} @media(max-width:480px){#odpc-tv-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}#odpc-tv-grid button{min-height:79px;font-size:12px}#odpc-tv-grid img{max-width:72px;height:28px}}</style>';
 $html.='<script src="https://cdn.jsdelivr.net/npm/hls.js@1.5.20/dist/hls.min.js"></script>';
 $html.='<script>(function(){const root=document.getElementById("odpc-tv");if(!root)return;const channels=JSON.parse(root.dataset.channels||"[]"),v=root.querySelector("video"),status=root.querySelector("#odpc-tv-status"),grid=root.querySelector("#odpc-tv-grid"),search=root.querySelector("#odpc-tv-search");let h=null,active="";function play(c){if(!c.available)return;if(h){h.destroy();h=null}v.pause();v.removeAttribute("src");v.load();active=c.name;status.textContent="Verbinde mit "+c.name+" …";render();if(window.Hls&&Hls.isSupported()){h=new Hls();h.loadSource(c.url);h.attachMedia(v);h.on(Hls.Events.MANIFEST_PARSED,()=>v.play().then(()=>status.textContent=c.name).catch(()=>status.textContent="Play drücken"));h.on(Hls.Events.ERROR,(_,e)=>{if(e.fatal)status.textContent=c.name+" derzeit nicht abspielbar"})}else if(v.canPlayType("application/vnd.apple.mpegurl")){v.src=c.url;v.play().then(()=>status.textContent=c.name).catch(()=>status.textContent="Play drücken")}else status.textContent="HLS nicht unterstützt"}function render(){grid.replaceChildren();const q=search.value.trim().toLowerCase();for(const c of channels){if(!c.name.toLowerCase().includes(q))continue;const b=document.createElement("button");b.type="button";b.disabled=!c.available;b.title=c.available?c.name:"Derzeit kein geeigneter HD-Stream verfügbar";if(active===c.name)b.className="active";const fallback=document.createElement("span");fallback.className="odpc-tv-fallback";fallback.textContent=c.name.slice(0,3).toUpperCase();if(c.logo){const img=document.createElement("img");img.src=c.logo;img.alt="";img.loading="lazy";img.onerror=()=>img.replaceWith(fallback);b.appendChild(img)}else b.appendChild(fallback);const label=document.createElement("span");label.className="odpc-tv-name";label.textContent=c.name;b.appendChild(label);b.onclick=()=>play(c);grid.appendChild(b)}}search.addEventListener("input",render);render()})();</script>';
 return $html;
